<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {ElMessageBox} from 'element-plus'
import {catalogSourceRows,catalogStyle,catalogStyleIdentities,patchCatalogSourceRows} from '@/api/modules/partnerCatalog'
import {operationCapabilities} from '@/api/modules/partnerOperations'
import {newRequestId} from '@/api/modules/partner'
import {cloneSelection,newSelectionRow,pasteSelectionRows,restrictedSelectionWriteFields} from '@/utils/partnerSelections'
import {partnerError} from '@/utils/partnerError'
import type {CatalogCodeOption,CatalogSource} from '@/types/partnerCatalog'
import type {SelectionRow} from '@/types/partnerSelections'
import SelectionRowEditor from '../selection/SelectionRowEditor.vue'
import PartnerPhoto from '../PartnerPhoto.vue'
const props=defineProps<{source:CatalogSource;suppliers:{code:string;name:string}[];canWrite:boolean}>(),emit=defineEmits<{close:[];changed:[]}>()
const rows=ref<SelectionRow[]>([]),total=ref(0),page=ref(1),keyword=ref(''),version=ref(props.source.version),loading=ref(false),busy=ref(false),error=ref(''),canReadCost=ref(false)
const editor=ref<SelectionRow>(),editorBaseline=ref(''),editorRequest=ref(''),cpMode=ref<'new'|'existing'>('new'),cpChoices=ref<CatalogCodeOption[]>([]),cpKeyword=ref(''),cpPage=ref(1),cpTotal=ref(0),cpId=ref<number>()
const pasteOpen=ref(false),pasteText=ref(''),pasted=ref<SelectionRow[]>([]),pastePage=ref(1),pasteRequest=ref('')
let generation=0
const editable=computed(()=>props.canWrite&&props.source.kind==='supplier_quote'&&props.source.canImport===true)
const supplierCode=computed(()=>props.source.supplierCode||'')
const pasteVisible=computed(()=>pasted.value.slice((pastePage.value-1)*20,pastePage.value*20))
async function load(){const seq=++generation;loading.value=true;error.value='';try{const result=await catalogSourceRows(props.source.id,{keyword:keyword.value.trim(),page:page.value,size:30});if(seq!==generation)return;rows.value=result.content;total.value=result.totalElements}catch(e){if(seq===generation)error.value=partnerError(e)}finally{if(seq===generation)loading.value=false}}
watch(()=>props.source.id,()=>{version.value=props.source.version;page.value=1;void load();void operationCapabilities().then(c=>{canReadCost.value=c.costs}).catch(e=>{error.value=partnerError(e)})},{immediate:true})
watch(()=>props.source.version,value=>{version.value=value})
onBeforeUnmount(()=>{generation++})
async function edit(row?:SelectionRow){error.value='';cpMode.value='new';cpId.value=undefined;cpChoices.value=[];cpPage.value=1;try{if(row){const detail=await catalogStyle(supplierCode.value,{sourceKind:'quote',recordId:props.source.id,rowId:row.rowId});editor.value={...newSelectionRow(),...cloneSelection(row),fileDetails:detail.fileDetails||[],phones:detail.phones||[]}}else editor.value={...newSelectionRow(),supplierCode:supplierCode.value};editorBaseline.value=JSON.stringify(editor.value);editorRequest.value=newRequestId()}catch(e){error.value=partnerError(e)}}
async function closeEditor(){if(!editor.value)return;if(JSON.stringify(editor.value)!==editorBaseline.value||cpMode.value==='existing')try{await ElMessageBox.confirm('放弃本款尚未保存的内容？','保留填写',{confirmButtonText:'放弃修改',cancelButtonText:'继续填写',closeOnClickModal:false})}catch{return}editor.value=undefined}
async function searchCp(reset=false){if(reset)cpPage.value=1;try{const result=await catalogStyleIdentities({supplierCode:supplierCode.value,keyword:cpKeyword.value.trim(),page:cpPage.value,size:20});cpChoices.value=result.content;cpTotal.value=result.totalElements}catch(e){error.value=partnerError(e)}}
function changes(row:SelectionRow){const value=cloneSelection(row) as unknown as Record<string,unknown>;for(const field of ['rowId','rowVersion','sortOrder','catalogStyleCode','catalogStyleLabel','fileDetails','phones','availablePhones','unavailablePhones','rangeSnapshots','sourcePhoneModelIds','sourcePhones','rawQuoteFields','confirmationSnapshot','confirmed','confirmedAt','sampleBatches','productId','specId','specLinks','specIds','productCode'])delete value[field];if(!canReadCost.value)for(const field of restrictedSelectionWriteFields)delete value[field];return value as Partial<SelectionRow>}
async function saveEditor(){if(!editor.value||busy.value||!editable.value||cpMode.value==='existing'&&!cpId.value)return;busy.value=true;error.value='';try{const row=editor.value,value=changes(row);if(!row.catalogStyleId&&cpMode.value==='existing')value.catalogStyleId=cpId.value;const result=await patchCatalogSourceRows(props.source.id,{version:version.value,requestId:editorRequest.value,operations:[{rowId:row.rowId,rowVersion:row.rowVersion||0,changes:value}]});version.value=result.version;editor.value=undefined;emit('changed');await load()}catch(e){error.value=partnerError(e)}finally{busy.value=false}}
function beginPaste(){pasteOpen.value=true;pasteText.value='';pasted.value=[];pastePage.value=1;pasteRequest.value=newRequestId()}
function previewPaste(){try{pasted.value=pasteSelectionRows(pasteText.value).map(row=>({...row,supplierCode:supplierCode.value}));pastePage.value=1;error.value=''}catch(e){error.value=partnerError(e)}}
async function closePaste(){if(busy.value)return;if(pasteText.value.trim())try{await ElMessageBox.confirm('放弃本次尚未保存的粘贴内容？','保留本次录入',{confirmButtonText:'放弃并关闭',cancelButtonText:'继续填写',closeOnClickModal:false})}catch{return}pasteOpen.value=false}
async function savePaste(){if(!pasted.value.length||busy.value||!editable.value)return;busy.value=true;error.value='';try{const result=await patchCatalogSourceRows(props.source.id,{version:version.value,requestId:pasteRequest.value,operations:pasted.value.map(row=>({rowId:row.rowId,rowVersion:0,changes:changes(row)}))});version.value=result.version;pasteOpen.value=false;emit('changed');await load()}catch(e){error.value=partnerError(e)}finally{busy.value=false}}
function close(){if(!busy.value&&!editor.value&&!pasteOpen.value)emit('close')}
</script>
<template><el-dialog :model-value="!editor&&!pasteOpen" title="供应商目录在线录入" width="min(1180px,96vw)" top="20px" class="catalog-online-dialog" append-to-body :close-on-click-modal="false" :before-close="close"><div class="online-content"><p class="online-note">{{source.name}} · 原件导入和在线录入写入同一目录；保存只分配／关联CP，不建选样、产品或样品。</p><div class="online-toolbar"><el-input v-model="keyword" clearable placeholder="搜索本份资料款式／供方款号" @keyup.enter="page=1;load()"/><el-button @click="page=1;load()">查询</el-button><el-button v-if="editable" @click="beginPaste">Excel矩形粘贴</el-button><el-button v-if="editable" type="primary" @click="edit()">新增款式</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="online-list" v-loading="loading"><article v-for="row in rows" :key="row.rowId"><PartnerPhoto v-if="row.fileDetails?.find(file=>file.type.startsWith('image/'))" :id="row.fileDetails.find(file=>file.type.startsWith('image/'))!.id"/><div><strong>{{row.name}}</strong><small>{{row.catalogStyleLabel||row.catalogStyleCode||'待分配款式号'}}</small></div><strong>{{row.modelText||'型号待补'}}</strong><span>{{row.color||'颜色待补'}}</span><el-button link type="primary" @click="edit(row)">{{editable?'维护本款':'查看本款'}}</el-button></article><el-empty v-if="!loading&&!rows.length" description="暂无款式；可新增或从Excel整块粘贴"/></div><el-pagination :current-page="page" :page-size="30" :total="total" :pager-count="5" layout="total,prev,pager,next" @current-change="page=$event;load()"/></div><template #footer><el-button :disabled="busy" @click="close">返回来源资料</el-button></template></el-dialog>
<el-dialog :model-value="!!editor" title="供应商款式资料" width="min(1020px,96vw)" top="20px" class="catalog-online-dialog" append-to-body :close-on-click-modal="false" :before-close="closeEditor"><template v-if="editor"><el-alert v-if="error" :title="error" type="error" :closable="false"/><section v-if="!editor.catalogStyleId" class="online-cp"><el-radio-group v-model="cpMode" @change="$event==='existing'&&searchCp(true)"><el-radio value="new">本款新分配CP</el-radio><el-radio value="existing">明确沿用已有同款CP</el-radio></el-radio-group><template v-if="cpMode==='existing'"><form class="online-toolbar" @submit.prevent="searchCp(true)"><el-input v-model="cpKeyword" placeholder="搜索已有款式号／名称"/><el-button native-type="submit">查询款式号</el-button></form><el-select v-model="cpId" clearable placeholder="选择已核实的同款，不按名称自动合并"><el-option v-for="option in cpChoices" :key="option.id" :value="option.id" :label="(option.label||option.code)+' · '+option.name+' · '+option.supplierName"/></el-select><el-pagination :current-page="cpPage" :page-size="20" :total="cpTotal" layout="prev,pager,next" @current-change="cpPage=$event;searchCp()"/></template></section><p v-if="!editor.rowVersion&&!editor.currency" class="online-note">未填写币种时默认人民币（CNY）；原件有其他币种请明确选择。</p><SelectionRowEditor context="catalog" :row="editor" :files="editor.fileDetails||[]" :library-files="source.files||[]" :suppliers="suppliers.filter(s=>s.code===supplierCode)" :can-write="editable&&!busy" :can-read-cost="canReadCost"/></template><template #footer><el-button :disabled="busy" @click="closeEditor">取消</el-button><el-button v-if="editable" type="primary" :disabled="!editor?.name.trim()||busy||cpMode==='existing'&&!cpId" :loading="busy" @click="saveEditor">保存供应商款式</el-button></template></el-dialog>
<el-dialog :model-value="pasteOpen" title="Excel矩形粘贴到供应商目录" width="min(1020px,96vw)" top="20px" class="catalog-online-dialog" append-to-body :close-on-click-modal="false" :show-close="!busy" :close-on-press-escape="!busy" :before-close="closePaste"><p class="online-note">可带已有中文表头；起订数量、单位、口径分别填列。粘贴新行默认新款，不从技术ID或名称猜关联；需要沿用已有CP请逐款明确选择。</p><el-input v-model="pasteText" type="textarea" :rows="6" @input="pasted=[]"/><el-alert v-if="error" :title="error" type="error" :closable="false"/><p v-if="pasted.length">拟新增{{pasted.length}}款；只写供应商目录。</p><div class="paste-preview"><article v-for="row in pasteVisible" :key="row.rowId"><strong>{{row.name}}</strong><span>{{row.modelText}}</span><span>颜色：{{row.color}}</span><span>材质：{{row.material}}</span><span>起订数量：{{row.moqQuantity??'未确认'}}</span><span>单位：{{row.moqUnit||'未确认'}}</span><span>口径：{{row.moqScope||'未确认'}}</span></article></div><el-pagination v-if="pasted.length>20" v-model:current-page="pastePage" :page-size="20" :total="pasted.length" layout="prev,pager,next"/><template #footer><el-button :disabled="busy" @click="closePaste">取消</el-button><el-button :disabled="busy" @click="previewPaste">预览本次粘贴</el-button><el-button type="primary" :disabled="!pasted.length||busy" :loading="busy" @click="savePaste">确认新增到目录</el-button></template></el-dialog></template>
<style scoped>:global(.catalog-online-dialog){display:flex;flex-direction:column;max-height:calc(100dvh - 40px);margin-bottom:20px}:global(.catalog-online-dialog>.el-dialog__body){min-height:0;overflow-y:auto}:global(.catalog-online-dialog>.el-dialog__footer){display:flex;justify-content:flex-end;gap:7px;flex-wrap:wrap}.online-content{display:flex;flex-direction:column;gap:8px;min-height:0;min-width:0}.online-note{font-size:12px;line-height:1.6;margin:0;overflow-wrap:anywhere;color:var(--el-text-color-secondary)}.online-toolbar{display:flex;gap:7px;flex-wrap:wrap;min-width:0}.online-toolbar>.el-input{flex:1;min-width:180px}.online-list{max-height:55dvh;min-height:100px;overflow-y:auto}.online-list article{display:flex;gap:8px;align-items:center;flex-wrap:wrap;border-bottom:1px solid var(--el-border-color-lighter);padding:6px 0;font-size:13px;min-width:0}.online-list article>div{flex:1;min-width:140px;overflow-wrap:anywhere}.online-list small{display:block;color:var(--el-text-color-secondary);font-size:12px}.online-cp{display:flex;flex-direction:column;gap:7px;margin-bottom:10px}.paste-preview{font-size:13px}.paste-preview article{display:flex;gap:4px 12px;flex-wrap:wrap;padding:6px 0;border-bottom:1px solid var(--el-border-color-lighter);overflow-wrap:anywhere}.paste-preview article>strong{flex-basis:100%}</style>
